     1→/**
     2→ * Image Generation Service
     3→ * Client for OpenRouter API using Gemini 2.5 Flash Preview Image model for outfit visualization
     4→ *
     5→ * Features:
     6→ * - Fashion-specific prompt engineering
     7→ * - Error handling with retries
     8→ * - Timeout protection
     9→ * - Rate limiting awareness
    10→ */
    11→
    12→import type { ImageGenerationRequest, ImageGenerationResponse, FlatLayRequest } from '../types/image-types';
    13→import { buildFlatLayPrompt, buildFashionPrompt } from '../prompts/image-prompts';
    14→
    15→/**
    16→ * OpenRouter API configuration
    17→ */
    18→const OPENROUTER_CONFIG = {
    19→  /** OpenRouter API base URL */
    20→  baseUrl: 'https://openrouter.ai/api/v1',
    21→  /**
    22→   * Model ID for Gemini 3 Pro Image Preview - Nano Banana Pro (text-to-image capable)
    23→   * Google's most advanced image-generation and editing model
    24→   */
    25→  model: 'google/gemini-2.5-flash-image',
    26→  /** Request timeout in milliseconds */
    27→  timeout: 30000,
    28→  /** Maximum retry attempts on failure */
    29→  maxRetries: 2,
    30→  /** Exponential backoff base delay (ms) */
    31→  retryDelay: 1000,
    32→};
    33→
    34→/**
    35→ * OpenRouter Image Generation Client
    36→ * Handles communication with OpenRouter API for outfit image generation
    37→ */
    38→export class OpenRouterImageClient {
    39→  private apiKey: string;
    40→  private requestCount: number = 0;
    41→  private lastRequestTime: number = 0;
    42→
    43→  /**
    44→   * Creates a new OpenRouter image client
    45→   *
    46→   * @param apiKey - OpenRouter API key
    47→   * @throws Error if API key is not provided
    48→   */
    49→  constructor(apiKey: string) {
    50→    if (!apiKey || typeof apiKey !== 'string' || apiKey.trim() === '') {
    51→      throw new Error('OpenRouter API key is required');
    52→    }
    53→    this.apiKey = apiKey;
    54→  }
    55→
    56→  /**
    57→   * Configuration for fitting model generation
    58→   */
    59→  private static readonly FITTING_MODEL_CONFIG = {
    60→    /** Extended timeout for fitting model generation (60 seconds) */
    61→    timeout: 60000,
    62→  };
    63→
    64→  /**
    65→   * Generates an outfit image from description using Gemini 2.5 Flash Preview
    66→   *
    67→   * @param description - Outfit description extracted from conversation
    68→   * @param options - Optional style parameters
    69→   * @returns Promise resolving to image generation response
    70→   *
    71→   * @example
    72→   * const client = new OpenRouterImageClient(apiKey);
    73→   * const response = await client.generateOutfitImage(
    74→   *   "White shirt with black pants for business meeting",
    75→   *   { style: { composition: 'flat-lay' } }
    76→   * );
    77→   */
    78→  async generateOutfitImage(
    79→    description: string,
    80→    options?: ImageGenerationRequest['style']
    81→  ): Promise<ImageGenerationResponse> {
    82→    // Validate input
    83→    if (!description || typeof description !== 'string' || description.trim() === '') {
    84→      return {
    85→        success: false,
    86→        error: 'INVALID_DESCRIPTION',
    87→        message: 'Outfit description is required',
    88→      };
    89→    }
    90→
    91→    // Check client-side rate limiting (basic protection)
    92→    if (!this.checkRateLimit()) {
    93→      return {
    94→        success: false,
    95→        error: 'RATE_LIMITED',
    96→        message: 'Too many requests. Please wait a moment before trying again.',
    97→      };
    98→    }
    99→
   100→    // Attempt generation with retries
   101→    let lastError: Error | null = null;
   102→
