   749→      console.log('[ImageGen] Parsing response:', JSON.stringify(data).slice(0, 500));
   750→
   751→      if (data.choices && data.choices[0] && data.choices[0].message) {
   752→        const message = data.choices[0].message;
   753→
   754→        // Primary format: images array (OpenRouter standard)
   755→        if (message.images && Array.isArray(message.images) && message.images.length > 0) {
   756→          const imageData = message.images[0];
   757→          console.log('[ImageGen] Found image in images array, type:', typeof imageData);
   758→
   759→          // Images are returned as data URLs (data:image/png;base64,...)
   760→          if (typeof imageData === 'string' && imageData.startsWith('data:image')) {
   761→            return { base64: imageData };
   762→          }
   763→
   764→          // Or as object with nested structure: {"type":"image_url","image_url":{"url":"data:..."}}
   765→          if (typeof imageData === 'object') {
   766→            // Check for image_url.url format (OpenRouter Gemini format)
   767→            if (imageData.image_url?.url) {
   768→              console.log('[ImageGen] Found image in image_url.url format');
   769→              const url = imageData.image_url.url;
   770→              if (url.startsWith('data:image')) {
   771→                return { base64: url };
   772→              }
   773→              return { url };
   774→            }
   775→            // Check for b64_json format
   776→            if (imageData.b64_json) {
   777→              return { base64: `data:image/png;base64,${imageData.b64_json}` };
   778→            }
   779→            // Check for direct base64/url
   780→            if (imageData.base64) {
   781→              return { base64: imageData.base64.startsWith('data:') ? imageData.base64 : `data:image/png;base64,${imageData.base64}` };
   782→            }
   783→            if (imageData.url) {
   784→              return { url: imageData.url };
   785→            }
   786→          }
   787→        }
   788→
   789→        // Check content for embedded base64 or URLs
   790→        const content = message.content;
   791→        if (typeof content === 'string') {
   792→          // Check if content contains base64 image data
   793→          const base64Match = content.match(/data:image\/(png|jpeg|jpg|webp);base64,[A-Za-z0-9+/=]+/);
   794→          if (base64Match) {
   795→            console.log('[ImageGen] Found base64 image in content');
   796→            return { base64: base64Match[0] };
   797→          }
   798→
   799→          // Check for URL in content
   800→          const urlMatch = content.match(/(https?:\/\/[^\s<>"]+\.(png|jpg|jpeg|gif|webp))/i);
   801→          if (urlMatch) {
   802→            console.log('[ImageGen] Found URL in content');
   803→            return { url: urlMatch[0] };
   804→          }
   805→        }
   806→
   807→        // Check for structured image data (fallback)
   808→        if (message.image) {
   809→          console.log('[ImageGen] Found image in message.image');
   810→          return {
   811→            base64: message.image.base64 || (message.image.b64_json ? `data:image/png;base64,${message.image.b64_json}` : undefined),
   812→            url: message.image.url,
   813→          };
   814→        }
   815→      }
   816→
   817→      // Fallback: return empty (will need to handle in caller)
   818→      console.warn('[ImageGen] Could not parse image from response. Keys:', Object.keys(data));
   819→      if (data.choices?.[0]?.message) {
   820→        console.warn('[ImageGen] Message keys:', Object.keys(data.choices[0].message));
   821→      }
   822→      return {};
   823→    } catch (error) {
   824→      console.error('[ImageGen] Error parsing image response:', error);
   825→      return {};
   826→    }
   827→  }
   828→
   829→  /**
   830→   * Client-side rate limiting check
   831→   * Limits to approximately 10 requests per minute
   832→   *
   833→   * @private
   834→   */
   835→  private checkRateLimit(): boolean {
   836→    const now = Date.now();
   837→    const minuteAgo = now - 60000;
   838→
   839→    // Reset counter if a minute has passed
   840→    if (this.lastRequestTime < minuteAgo) {
   841→      this.requestCount = 0;
   842→    }
   843→
   844→    // Check if under limit
   845→    if (this.requestCount >= 10) {
   846→      return false;
   847→    }
   848→
   849→    // Update counters
   850→    this.requestCount++;
   851→    this.lastRequestTime = now;
   852→
   853→    return true;
   854→  }
   855→
   856→  /**
   857→   * Checks if error is non-retryable (auth, validation, etc.)
   858→   *
   859→   * @private
   860→   */
   861→  private isNonRetryableError(error: any): boolean {
   862→    if (!error) return false;
   863→
   864→    const errorMessage = error.message || error.toString();
   865→
   866→    // Don't retry authentication errors
   867→    if (errorMessage.includes('401') || errorMessage.includes('403')) {
   868→      return true;
   869→    }
   870→
   871→    // Don't retry validation errors
   872→    if (errorMessage.includes('400') || errorMessage.includes('INVALID')) {
