/**
 * Image Generation API Route
 * POST /api/generate-image
 *
 * Handles outfit image generation requests using OpenRouter's Gemini 2.5 Flash Preview model
 *
 * Features:
 * - Server-side rate limiting (10 requests per minute per IP)
 * - Request validation
 * - Error handling with appropriate HTTP status codes
 * - Logging for debugging
 */

import { NextRequest, NextResponse } from 'next/server';
import { OpenRouterImageClient } from '@/lib/services/image-generation-service';
import { generateHybridFlatLayWithFallback } from '@/lib/services/hybrid-flat-lay-service';
import type { ImageGenerationRequest, FlatLayItem, BackgroundStyle, UserAesthetic } from '@/lib/types/image-types';
import fs from 'fs';
import path from 'path';
import { spawn } from 'child_process';

/**
 * Rate limiting configuration
 * Tracks request counts per IP address
 */
const rateLimitMap = new Map<string, { count: number; resetTime: number }>();
const RATE_LIMIT_WINDOW = 60000; // 1 minute in milliseconds
const RATE_LIMIT_MAX_REQUESTS = 10;

/**
 * Checks if request is rate limited
 *
 * @param ip - Client IP address
 * @returns true if rate limited, false if allowed
 */
function isRateLimited(ip: string): boolean {
  const now = Date.now();
  const record = rateLimitMap.get(ip);

  // No record or window expired - create new record
  if (!record || now > record.resetTime) {
    rateLimitMap.set(ip, {
      count: 1,
      resetTime: now + RATE_LIMIT_WINDOW,
    });
    return false;
  }

  // Increment count
  record.count++;

  // Check if over limit
  if (record.count > RATE_LIMIT_MAX_REQUESTS) {
    return true;
  }

  return false;
}

/**
 * Gets client IP address from request
 *
 * @param request - Next.js request object
 * @returns IP address string
 */
function getClientIP(request: NextRequest): string {
  // Try various headers that might contain the real IP
  const forwarded = request.headers.get('x-forwarded-for');
  if (forwarded) {
    return forwarded.split(',')[0].trim();
  }

  const realIP = request.headers.get('x-real-ip');
  if (realIP) {
    return realIP;
  }

  // Fallback to a default value
  return 'unknown';
}

/**
 * Ensures a directory exists, creating it if necessary
 *
 * @param dirPath - Absolute path to the directory
 */
function ensureDirectoryExists(dirPath: string): void {
  if (!fs.existsSync(dirPath)) {
    fs.mkdirSync(dirPath, { recursive: true });
    console.log('[API] Created directory:', dirPath);
  }
}

/**
 * Generates a unique filename for an outfit image
 *
 * @returns Filename in format: outfit-{timestamp}.png
 */
function generateImageFilename(): string {
  const timestamp = Date.now();
  return `outfit-${timestamp}.png`;
}

/**
 * Removes background from an image file using rembg Python script
 *
 * @param inputPath - Absolute path to the input image
 * @param outputPath - Absolute path to save the output image
 * @returns Promise that resolves to true on success, false on failure
 */
async function removeBackgroundFromFile(inputPath: string, outputPath: string): Promise<boolean> {
  return new Promise((resolve) => {
    const scriptPath = path.join(process.cwd(), '..', '..', 'scripts', 'image_processing', 'remove_bg_rembg.py');

    console.log('[API] Running background removal:', { inputPath, outputPath, scriptPath });

    const python = spawn('python3', [scriptPath, inputPath, outputPath]);

    let stderr = '';

    python.stderr.on('data', (data) => {
      stderr += data.toString();
      console.log('[API] Background removal:', data.toString().trim());
    });

    python.on('close', (code) => {
      if (code === 0) {
        console.log('[API] Background removal completed successfully');
        resolve(true);
      } else {
        console.error('[API] Background removal failed with code:', code);
        console.error('[API] stderr:', stderr);
        resolve(false);
      }
    });

    python.on('error', (err) => {
      console.error('[API] Failed to spawn background removal process:', err);
      resolve(false);
    });
  });
}

/**
 * Auto-crops image to the bounding box of non-transparent pixels with padding
 *
 * @param inputPath - Absolute path to the input image
 * @param outputPath - Absolute path to save the output image
 * @returns Promise that resolves to true on success, false on failure
 */
async function autoCropSubject(inputPath: string, outputPath: string): Promise<boolean> {
  return new Promise((resolve) => {
    const scriptPath = path.join(process.cwd(), '..', '..', 'scripts', 'image_processing', 'auto_crop_subject.py');

    console.log('[API] Running auto-crop:', { inputPath, outputPath, scriptPath });

    const python = spawn('python3', [scriptPath, inputPath, outputPath]);

    let stderr = '';

    python.stderr.on('data', (data) => {
      stderr += data.toString();
      console.log('[API] Auto-crop:', data.toString().trim());
    });

    python.on('close', (code) => {
      if (code === 0) {
        console.log('[API] Auto-crop completed successfully');
        resolve(true);
      } else {
        console.error('[API] Auto-crop failed with code:', code);
        console.error('[API] stderr:', stderr);
        resolve(false);
      }
    });

    python.on('error', (err) => {
      console.error('[API] Failed to spawn auto-crop process:', err);
      resolve(false);
    });
  });
}

/**
 * Saves a base64-encoded image to disk as a PNG file
 *
 * @param base64Data - Base64 image data (with or without data URL prefix)
 * @param filename - Name of the file to save
 * @returns Relative public URL path to the saved image
 * @throws Error if file save fails
 */
function saveBase64Image(base64Data: string, filename: string): string {
  // Strip data URL prefix if present (e.g., "data:image/png;base64,")
  const base64Content = base64Data.includes(',')
    ? base64Data.split(',')[1]
    : base64Data;

  // Construct absolute path to the public/generated-images directory
  const publicDir = path.join(process.cwd(), 'public', 'generated-images');
  ensureDirectoryExists(publicDir);

  const filePath = path.join(publicDir, filename);

  // Convert base64 to buffer and write to file
  const imageBuffer = Buffer.from(base64Content, 'base64');
  fs.writeFileSync(filePath, imageBuffer);

  console.log('[API] Saved image to:', filePath);

  // Return public URL path (relative)
  return `/generated-images/${filename}`;
}

/**
 * POST handler for image generation
 *
 * Request body:
 * {
 *   description: string,
 *   style?: {
 *     photographyStyle?: string,
 *     composition?: string,
 *     lighting?: string,
 *     aestheticContext?: string
 *   }
 * }
 *
 * Response on success:
 * {
 *   success: true,
 *   imageUrl: string,        // Public URL path (e.g., /generated-images/outfit-1732800000000.png)
 *   imageBase64: string,      // Base64-encoded image data
 *   error?: undefined,
 *   message?: undefined
 * }
 *
 * Response on failure:
 * {
 *   success: false,
 *   imageUrl?: undefined,
 *   imageBase64?: undefined,
 *   error: string,
 *   message: string
 * }
 */
export async function POST(request: NextRequest) {
  const startTime = Date.now();

  try {
    // Get client IP for rate limiting
    const clientIP = getClientIP(request);

    console.log('[API] Image generation request received from IP:', clientIP);

    // Check rate limiting
    if (isRateLimited(clientIP)) {
      console.warn('[API] Rate limit exceeded for IP:', clientIP);
      return NextResponse.json(
        {
          success: false,
          error: 'RATE_LIMITED',
          message: 'Too many requests. Please wait a minute before trying again.',
        },
        {
          status: 429,
          headers: {
            'Retry-After': '60',
          },
        }
      );
    }

    // Check if OPENROUTER_API_KEY is configured
    const apiKey = process.env.OPENROUTER_API_KEY;
    if (!apiKey) {
      console.error('[API] OPENROUTER_API_KEY not configured');
      return NextResponse.json(
        {
          success: false,
          error: 'SERVICE_UNAVAILABLE',
          message: 'Image generation service is not configured. Please contact support.',
        },
        { status: 503 }
      );
    }

    // Parse request body
    let body: ImageGenerationRequest;
    try {
      body = await request.json();
    } catch (error) {
      console.error('[API] Invalid JSON in request body:', error);
      return NextResponse.json(
        {
          success: false,
          error: 'INVALID_REQUEST',
          message: 'Invalid request format',
        },
        { status: 400 }
      );
    }

    // Validate request body
    const { description, style, referenceImage, secondaryReferenceImage, generationType, flatLayItems, occasionContext, backgroundStyle, userAesthetic } = body;

    // Flat-lay and hybrid-flat-lay generation require items instead of description
    if (generationType === 'flat-lay' || generationType === 'hybrid-flat-lay') {
      if (!flatLayItems || !Array.isArray(flatLayItems) || flatLayItems.length === 0) {
        console.error('[API] Missing or invalid items for flat-lay generation');
        return NextResponse.json(
          {
            success: false,
            error: 'INVALID_ITEMS',
            message: 'At least one item is required for flat-lay generation',
          },
          { status: 400 }
        );
      }
    } else if (!description || typeof description !== 'string' || description.trim() === '') {
      console.error('[API] Missing or invalid description');
      return NextResponse.json(
        {
          success: false,
          error: 'INVALID_DESCRIPTION',
          message: 'Outfit description is required',
        },
        { status: 400 }
      );
    }

    // Validate description length (3000 chars for fitting-model, 1000 for outfit)
    // Skip validation for flat-lay and hybrid-flat-lay since they use items instead of description
    if (generationType !== 'flat-lay' && generationType !== 'hybrid-flat-lay') {
      const maxDescriptionLength = (generationType === 'fitting-model' || generationType === 'try-on' || generationType === 'try-on-dual') ? 3000 : 1000;
      if (description && description.length > maxDescriptionLength) {
        console.error('[API] Description too long:', description.length);
        return NextResponse.json(
          {
            success: false,
            error: 'DESCRIPTION_TOO_LONG',
            message: `Description is too long. Please keep it under ${maxDescriptionLength} characters.`,
          },
          { status: 400 }
        );
      }
    }

    // Validate referenceImage format when provided with fitting-model, try-on, or try-on-dual generation
    if ((generationType === 'fitting-model' || generationType === 'try-on' || generationType === 'try-on-dual') && referenceImage) {
      if (typeof referenceImage !== 'string' || referenceImage.trim() === '') {
        console.error('[API] Invalid reference image for', generationType, 'generation');
        return NextResponse.json(
          {
            success: false,
            error: 'INVALID_REFERENCE_IMAGE',
            message: 'Reference image must be a valid string',
          },
          { status: 400 }
        );
      }

      if (!referenceImage.startsWith('data:image/')) {
        console.error('[API] Invalid reference image format');
        return NextResponse.json(
          {
            success: false,
            error: 'INVALID_REFERENCE_IMAGE_FORMAT',
            message: 'Reference image must be a base64 data URL (e.g., data:image/jpeg;base64,...)',
          },
          { status: 400 }
        );
      }
    }

    // Validate that try-on and try-on-dual generation require a reference image
    if ((generationType === 'try-on' || generationType === 'try-on-dual') && !referenceImage) {
      console.error('[API] Missing reference image for', generationType, 'generation');
      return NextResponse.json(
        {
          success: false,
          error: 'MISSING_REFERENCE_IMAGE',
          message: 'Reference image (fitting model) is required for try-on generation',
        },
        { status: 400 }
      );
    }

    // Validate secondaryReferenceImage format when provided (required for try-on-dual)
    if (generationType === 'try-on-dual') {
      if (!secondaryReferenceImage) {
        console.error('[API] Missing secondary reference image for try-on-dual generation');
        return NextResponse.json(
          {
            success: false,
            error: 'MISSING_SECONDARY_REFERENCE_IMAGE',
            message: 'Secondary reference image (flat-lay) is required for try-on-dual generation',
          },
          { status: 400 }
        );
      }

      if (typeof secondaryReferenceImage !== 'string' || !secondaryReferenceImage.startsWith('data:image/')) {
        console.error('[API] Invalid secondary reference image format');
        return NextResponse.json(
          {
            success: false,
            error: 'INVALID_SECONDARY_REFERENCE_IMAGE_FORMAT',
            message: 'Secondary reference image must be a base64 data URL (e.g., data:image/jpeg;base64,...)',
          },
          { status: 400 }
        );
      }
    }

    console.log('[API] Generating image:', {
      descriptionLength: description?.length || 0,
      style: style || 'default',
      generationType: generationType || 'outfit',
      hasReferenceImage: !!referenceImage,
      hasSecondaryReferenceImage: !!secondaryReferenceImage,
      flatLayItemCount: flatLayItems?.length || 0,
      backgroundStyle: backgroundStyle || 'auto',
      userAesthetic: userAesthetic || 'none',
    });

    // Create image client and generate image
    const imageClient = new OpenRouterImageClient(apiKey);

    // Route to appropriate generation method based on generationType
    let result;
    if (generationType === 'hybrid-flat-lay' && flatLayItems) {
      // Hybrid flat-lay: AI background + real product images
      const hybridResult = await generateHybridFlatLayWithFallback(
        {
          items: flatLayItems,
          backgroundStyle: backgroundStyle as BackgroundStyle | undefined,
          userAesthetic: userAesthetic as UserAesthetic | undefined,
          occasionContext: occasionContext,
        },
        apiKey
      );

      // Convert hybrid response to standard ImageGenerationResponse format
      result = {
        success: hybridResult.success,
        imageBase64: hybridResult.imageBase64,
        imageUrl: hybridResult.imageUrl,
        error: hybridResult.error,
        message: hybridResult.message,
        metadata: {
          model: 'hybrid-flat-lay',
          generatedAt: new Date().toISOString(),
          prompt: `Hybrid flat-lay with ${hybridResult.processedProducts.length} products`,
        },
      };
    } else if (generationType === 'flat-lay' && flatLayItems) {
      result = await imageClient.generateFlatLayImage({
        items: flatLayItems,
        occasionContext: occasionContext,
        totalItems: flatLayItems.length,
      });
    } else if (generationType === 'fitting-model' && referenceImage) {
      result = await imageClient.generateFittingModelImage(description, referenceImage);
    } else if (generationType === 'try-on-dual' && referenceImage && secondaryReferenceImage) {
      // Try-on with dual reference: fitting model (IMAGE 1) + flat-lay (IMAGE 2)
      result = await imageClient.generateTryOnWithDualReference(description, referenceImage, secondaryReferenceImage);
    } else if (generationType === 'try-on' && referenceImage) {
      // Try-on with single reference: fitting model only (fallback mode)
      result = await imageClient.generateFittingModelImage(description, referenceImage);
    } else {
      result = await imageClient.generateOutfitImage(description, style);
    }

    const duration = Date.now() - startTime;
    console.log('[API] Image generation completed in', duration, 'ms', {
      success: result.success,
      error: result.error || 'none',
    });

    // Return response with appropriate status code
    if (result.success) {
      // Save image to disk and add imageUrl to response
      if (result.imageBase64) {
        try {
          const filename = generateImageFilename();
          const imageUrl = saveBase64Image(result.imageBase64, filename);
          const publicDir = path.join(process.cwd(), 'public', 'generated-images');
          const filePath = path.join(publicDir, filename);

          // Apply background removal for fitting-model, try-on, and try-on-dual images
          if (generationType === 'fitting-model' || generationType === 'try-on' || generationType === 'try-on-dual') {
            console.log('[API] Applying background removal for', generationType);
            const bgRemovalSuccess = await removeBackgroundFromFile(filePath, filePath);

            if (bgRemovalSuccess) {
              // Re-read the processed image and update base64
              const processedImageBuffer = fs.readFileSync(filePath);
              result.imageBase64 = `data:image/png;base64,${processedImageBuffer.toString('base64')}`;
              console.log('[API] Background removed successfully');

              // Apply auto-crop to ensure model fills the frame
              console.log('[API] Applying auto-crop for', generationType);
              const autoCropSuccess = await autoCropSubject(filePath, filePath);

              if (autoCropSuccess) {
                // Re-read the cropped image and update base64
                const croppedImageBuffer = fs.readFileSync(filePath);
                result.imageBase64 = `data:image/png;base64,${croppedImageBuffer.toString('base64')}`;
                console.log('[API] Auto-crop completed successfully');
              } else {
                console.warn('[API] Auto-crop failed, using image with background removed');
              }
            } else {
              console.warn('[API] Background removal failed, using original image');
            }
          }

          // Add imageUrl to the result
          result.imageUrl = imageUrl;

          console.log('[API] Image saved successfully:', imageUrl);
        } catch (saveError) {
          // Log error but don't fail the request - base64 is still available
          console.error('[API] Failed to save image to disk:', saveError);
          console.warn('[API] Continuing without imageUrl - base64 still available');
        }
      }

      return NextResponse.json(result, {
        status: 200,
        headers: {
          'Cache-Control': 'no-cache, no-store, must-revalidate',
        },
      });
    } else {
      // Determine status code based on error type
      let statusCode = 500;
      if (result.error === 'RATE_LIMITED') {
        statusCode = 429;
      } else if (result.error === 'INVALID_DESCRIPTION') {
        statusCode = 400;
      } else if (result.error === 'SERVICE_UNAVAILABLE') {
        statusCode = 503;
      }

      return NextResponse.json(result, {
        status: statusCode,
      });
    }
  } catch (error) {
    const duration = Date.now() - startTime;
    console.error('[API] Unexpected error during image generation:', error);
    console.error('[API] Error occurred after', duration, 'ms');

    return NextResponse.json(
      {
        success: false,
        error: 'INTERNAL_ERROR',
        message: 'An unexpected error occurred. Please try again later.',
      },
      { status: 500 }
    );
  }
}

/**
 * GET handler - not supported
 * Returns 405 Method Not Allowed
 */
export async function GET() {
  return NextResponse.json(
    {
      success: false,
      error: 'METHOD_NOT_ALLOWED',
      message: 'GET method is not supported. Use POST to generate images.',
    },
    { status: 405 }
  );
}

/**
 * OPTIONS handler for CORS preflight
 */
export async function OPTIONS() {
  return NextResponse.json(
    {},
    {
      status: 200,
      headers: {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Methods': 'POST, OPTIONS',
        'Access-Control-Allow-Headers': 'Content-Type',
      },
    }
  );
}

/**
 * Image Generation Prompt Templates
 *
 * Centralised prompt module for all AI image generation features.
 * Every prompt follows Google Gemini 2.5 Flash Image best practices:
 *   - Narrative-descriptive paragraphs (no keyword lists)
 *   - Positive framing only (zero negative instructions)
 *   - Commercial safety context (e-commerce / fashion catalog / editorial)
 *   - Explicit aspect-ratio hint at the end of each prompt
 */

import type { FlatLayItem, BackgroundStyle, ImageConfig } from '@/lib/types/image-types';

// ---------------------------------------------------------------------------
// Utility helpers (moved from image-generation-service.ts)
// ---------------------------------------------------------------------------

/**
 * Checks whether a string looks like a product name or SKU code.
 * Product names often contain brand names, SKU codes, or marketing text
 * that would cause the AI to render unwanted text labels on the image.
 */
export function containsProductNameOrSku(text: string): boolean {
  // Check for SKU-like patterns (alphanumeric codes)
  const skuPattern = /[A-Z]{2,}[0-9]{4,}|[0-9]{8,}/i;
  if (skuPattern.test(text)) return true;

  // Check for common product name indicators
  const productNameIndicators = [
    /\b(online exclusive|limited edition|new arrival)\b/i,
    /\b(korea|korean|japan|japanese)\b/i, // Region markers often in product names
    /[A-Z][a-z]+[A-Z]/, // CamelCase brand names
    /\b\w{10,}\b/, // Very long words (likely brand names or codes)
  ];

  return productNameIndicators.some(pattern => pattern.test(text));
}

/**
 * Normalises a product category string to a clean, singular fashion term
 * suitable for use inside an image prompt.
 */
export function cleanCategoryForPrompt(category: string): string {
  const categoryMap: Record<string, string> = {
    'dress': 'Dress',
    'dresses': 'Dress',
    'top': 'Top',
    'tops': 'Top',
    'blouse': 'Blouse',
    'blouses': 'Blouse',
    'shirt': 'Shirt',
    'shirts': 'Shirt',
    'pants': 'Pants',
    'trousers': 'Pants',
    'skirt': 'Skirt',
    'skirts': 'Skirt',
    'jacket': 'Jacket',
    'jackets': 'Jacket',
    'blazer': 'Blazer',
    'blazers': 'Blazer',
    'coat': 'Coat',
    'coats': 'Coat',
    'sweater': 'Sweater',
    'sweaters': 'Sweater',
    'cardigan': 'Cardigan',
    'cardigans': 'Cardigan',
    'shoes': 'Shoes',
    'shoe': 'Shoes',
    'footwear': 'Shoes',
    'heels': 'Heels',
    'sneakers': 'Sneakers',
    'sandals': 'Sandals',
    'boots': 'Boots',
    'bag': 'Bag',
    'bags': 'Bag',
    'handbag': 'Handbag',
    'handbags': 'Handbag',
    'accessory': 'Accessory',
    'accessories': 'Accessory',
    'jewelry': 'Jewelry',
    'watch': 'Watch',
    'watches': 'Watch',
    'belt': 'Belt',
    'belts': 'Belt',
    'scarf': 'Scarf',
    'scarves': 'Scarf',
    'hat': 'Hat',
    'hats': 'Hat',
    'leggings': 'Leggings',
    'shorts': 'Shorts',
    'jeans': 'Jeans',
    'jumpsuit': 'Jumpsuit',
    'romper': 'Romper',
  };

  const lowerCategory = category.toLowerCase().trim();
  return categoryMap[lowerCategory] || category;
}

// ---------------------------------------------------------------------------
// 1. Flat-lay prompt
// ---------------------------------------------------------------------------

/**
 * Builds a narrative flat-lay prompt from an array of outfit items.
 * Uses only generic category + colour descriptions to keep the generated
 * image free of rendered text labels.
 */
export function buildFlatLayPrompt(
  items: FlatLayItem[],
  occasionContext?: string,
): string {
  const itemDescriptions = items
    .map((item) => {
      // Prefer a clean visual description when available
      if (item.visualDescription && !containsProductNameOrSku(item.visualDescription)) {
        return `a ${item.category.toLowerCase()} described as ${item.visualDescription}`;
      }
      // Fallback to category + colour only
      const colorInfo = item.color ? `${item.color} ` : '';
      const clean = cleanCategoryForPrompt(item.category);
      return `a ${colorInfo}${clean.toLowerCase()}`;
    })
    .join(', ');

  const itemCount = items.length;
  const occasionLine = occasionContext ? ` Styled for ${occasionContext}.` : '';

  return `A high-resolution, studio-lit flat-lay photograph showing ${itemCount} fashion items arranged as a single coordinated outfit on a pristine white surface. The items are: ${itemDescriptions}. The composition uses balanced spacing with each piece clearly visible and proportionally sized. Photographed from directly overhead with soft, diffused three-point lighting that eliminates harsh shadows and preserves accurate colours. Professional e-commerce product photography quality with sharp focus across all items. Clean, minimal styling typical of luxury fashion editorial flat-lay.${occasionLine} Square 1:1 format.`;
}

// ---------------------------------------------------------------------------
// 2. Fashion / outfit prompt
// ---------------------------------------------------------------------------

/**
 * Builds a narrative fashion-outfit prompt for model-worn imagery.
 */
export function buildFashionPrompt(
  description: string,
  options?: {
    photographyStyle?: string;
    composition?: string;
    lighting?: string;
    aestheticContext?: string;
  },
): string {
  const photographyStyle = options?.photographyStyle || 'editorial fashion';
  const composition = options?.composition || 'full-body model shoot';
  const lighting = options?.lighting || 'studio';
  const aesthetic = options?.aestheticContext || 'modern international';

  return `A professional fashion editorial photograph of a real person wearing the following outfit: ${description}. The shot is composed as a ${composition} in ${photographyStyle} style with ${lighting} lighting that produces clean, even illumination and accurate colour reproduction. The background is minimal and uncluttered, letting the outfit remain the focal point. The overall aesthetic is ${aesthetic} fashion with an elegant, contemporary Thai sensibility. Every garment detail is rendered with sharp focus and true-to-life colour, meeting the standard expected of high-end fashion e-commerce product photography. Portrait 3:4 format.`;
}

// ---------------------------------------------------------------------------
// 3. Fitting model prompt (reference-based)
// ---------------------------------------------------------------------------

/**
 * Returns the narrative prompt for generating a fitting model from a
 * user's reference photo. The model wears a standard outfit
 * (white crop top + black shorts, barefoot).
 */
export function buildFittingModelPrompt(): string {
  return `A professional e-commerce fashion catalog photograph of a person matching the reference image exactly. The model stands in a symmetrical forward-facing pose with arms relaxed at sides and feet together, wearing a white spaghetti strap crop top paired with black high-waisted legging shorts, barefoot. The face, skin tone, hair, and body proportions are a precise match to the reference photo with no idealization or modification. The setting is a pure white infinity cove studio backdrop with bright, high-key front-facing softbox lighting that creates a clean, cutout-ready image with no visible floor, ground, or shadows on the backdrop. Professional product photography standard with sharp detail and accurate skin tone reproduction. Portrait 3:4 format.`;
}

// ---------------------------------------------------------------------------
// 4. Mystery model prompt (no reference photo)
// ---------------------------------------------------------------------------

/**
 * Returns the narrative prompt for generating a default "mystery" fitting
 * model when the user has not uploaded a reference photo.
 */
export function buildMysteryModelPrompt(): string {
  return `A professional e-commerce fashion catalog photograph of a young Thai woman with warm brown eyes, soft natural makeup, and shoulder-length straight black hair. She stands in a symmetrical forward-facing pose with arms relaxed at sides and feet together, wearing a white spaghetti strap crop top paired with black high-waisted legging shorts, barefoot. Her expression is friendly and confident with a natural, approachable beauty. The setting is a pure white infinity cove studio backdrop with bright, high-key front-facing softbox lighting that creates a clean, cutout-ready image with no visible floor, ground, or shadows on the backdrop. Professional product photography standard with sharp detail and accurate skin tone reproduction. Portrait 3:4 format.`;
}

// ---------------------------------------------------------------------------
// 5. Try-on prompt (single reference)
// ---------------------------------------------------------------------------

/**
 * Builds a narrative try-on prompt for showing an outfit on the user's
 * fitting model, given a single reference image.
 */
export function buildTryOnPrompt(
  items: Array<{ name: string; category?: string }>,
  outfitTitle?: string,
): string {
  const formatted = items
    .map((item) => item.name)
    .join(', ');

  const titleContext = outfitTitle ? ` (${outfitTitle})` : '';

  return `A professional e-commerce fashion catalog photograph of the person from the reference image wearing ${formatted}${titleContext}. The model's face, skin tone, hair, and body proportions are preserved exactly from the reference. The model stands in a confident forward-facing pose with feet together, filling 90-95% of the vertical frame. The outfit drapes naturally on the body with realistic fabric behavior, accurate colours, and proper layering. Set against a pure white infinity cove studio backdrop with high-key softbox lighting and no visible floor, ground, or backdrop shadows. Clean, cutout-ready product photo quality. Portrait 3:4 format.`;
}

// ---------------------------------------------------------------------------
// 6. Dual-reference try-on prompt (fitting model + flat-lay)
// ---------------------------------------------------------------------------

/**
 * Builds a narrative try-on prompt that references two images:
 *   IMAGE 1 — the user's fitting model (face/body)
 *   IMAGE 2 — the flat-lay showing the exact outfit items
 */
export function buildDualReferenceTryOnPrompt(
  items: Array<{ name: string; category?: string }>,
  outfitTitle?: string,
): string {
  const formatted = items
    .map((item) => item.name)
    .join(', ');

  const titleContext = outfitTitle ? ` (${outfitTitle})` : '';

  return `Transfer all fashion items from IMAGE 2 onto the person shown in IMAGE 1, creating a professional e-commerce fashion catalog photograph. The person's face, skin tone, hair, and body proportions from IMAGE 1 are preserved exactly. The model fills 90-95% of the vertical frame in a centred full-body standing pose. Every garment, accessory, and footwear piece visible in IMAGE 2 appears on the model with accurate colours, natural fabric draping, realistic shadows, and proper layering depth. Set against a pure white infinity cove studio backdrop with matching high-key softbox lighting and no visible floor or backdrop shadows. Items being shown: ${formatted}${titleContext}. Portrait 3:4 format.`;
}

// ---------------------------------------------------------------------------
// 7. Background prompts for hybrid flat-lay
// ---------------------------------------------------------------------------

const NARRATIVE_BACKGROUND_PROMPTS: Record<BackgroundStyle, string> = {
  'white-clean':
    'A pure white seamless surface photographed from directly overhead for flat-lay product photography. The surface is completely flat, solid white, and uniformly lit with soft diffused studio lighting that produces absolutely even illumination. The frame is entirely empty with a pristine, distraction-free finish suitable for premium e-commerce fashion imagery. Square 1:1 format.',

  'marble-white':
    'A luxurious white Carrara marble surface photographed from directly overhead for flat-lay fashion product photography. The surface features subtle natural grey veining patterns that evoke a quiet-luxury aesthetic. The marble is clean, smooth, and completely empty, styled as a premium backdrop for high-end fashion items. Soft diffused studio lighting creates even illumination across the entire surface. Square 1:1 format.',

  'marble-grey':
    'A polished grey marble surface with elegant white veining photographed from directly overhead for flat-lay fashion product photography. The tone is refined and professional, evoking a corporate-chic atmosphere suited to business and formalwear styling. The surface is completely empty and evenly lit with soft studio lighting that preserves the natural stone texture. Square 1:1 format.',

  'wood-light':
    'A light blonde oak wood grain surface photographed from directly overhead for flat-lay fashion product photography. The grain runs in gentle, natural lines with a warm Scandinavian feel that complements organic and bohemian fashion aesthetics. The surface is clean, completely empty, and lit with soft, even studio lighting that highlights the subtle wood texture. Square 1:1 format.',

  'wood-dark':
    'A rich dark walnut wood surface photographed from directly overhead for flat-lay fashion product photography. The deep, warm tones and refined grain create a dark-academia, scholarly library aesthetic. The surface is smooth, completely empty, and illuminated with soft diffused studio lighting that brings out the wood\'s natural depth. Square 1:1 format.',

  'linen-natural':
    'A natural undyed linen fabric surface photographed from directly overhead for flat-lay fashion product photography. The weave has a soft, organic texture in warm beige and cream tones, conveying a clean-girl effortless aesthetic. The fabric lies perfectly flat with a smooth finish and is completely empty, lit with gentle diffused studio lighting. Square 1:1 format.',

  'linen-grey':
    'A cool-toned grey linen fabric surface photographed from directly overhead for flat-lay fashion product photography. The subtle weave pattern creates a contemporary casual-chic backdrop with modern understated elegance. The fabric lies perfectly flat and smooth, completely empty, with even diffused studio lighting that preserves the textile detail. Square 1:1 format.',
};

/**
 * Returns a narrative background prompt for the given style.
 * Falls back to `white-clean` for unrecognised styles.
 */
export function buildBackgroundPrompt(style: BackgroundStyle): string {
  return NARRATIVE_BACKGROUND_PROMPTS[style] || NARRATIVE_BACKGROUND_PROMPTS['white-clean'];
}

// ---------------------------------------------------------------------------
// 10. Default image config
// ---------------------------------------------------------------------------

/**
 * Returns sensible default ImageConfig values (primarily aspect ratio)
 * for a given generation type.
 */
export function getDefaultImageConfig(generationType: string): ImageConfig {
  switch (generationType) {
    case 'flat-lay':
    case 'hybrid-flat-lay':
      return { aspect_ratio: '1:1' };
    case 'fitting-model':
    case 'try-on':
    case 'try-on-dual':
    case 'outfit':
    default:
      return { aspect_ratio: '3:4' };
  }
}

