## Task 4: Create API Route

Create `apps/web/app/api/occasion-flat-lay/route.ts` following the EXACT same patterns as the existing `apps/web/app/api/generate-image/route.ts`. Key things to reuse:

- Same rate limiting pattern (rateLimitMap, isRateLimited, getClientIP functions — copy them)
- Same saveBase64Image pattern
- Same error response structure

```typescript
/**
 * Occasion Flat-Lay Generation API Route
 * POST /api/occasion-flat-lay
 */

import { NextRequest, NextResponse } from 'next/server';
import { generateOccasionFlatLay } from '@/lib/services/occasion-flat-lay-service';
import type { OccasionFlatLayRequest, OccasionPreset } from '@/lib/types/image-types';
import fs from 'fs';
import path from 'path';

// Rate limiting (same pattern as generate-image route)
const rateLimitMap = new Map<string, { count: number; resetTime: number }>();
const RATE_LIMIT_WINDOW = 60000;
const RATE_LIMIT_MAX_REQUESTS = 10;

const VALID_PRESETS: OccasionPreset[] = ['weekend-social', 'date-night', 'everyday-casual'];

function isRateLimited(ip: string): boolean {
  const now = Date.now();
  const record = rateLimitMap.get(ip);
  if (!record || now > record.resetTime) {
    rateLimitMap.set(ip, { count: 1, resetTime: now + RATE_LIMIT_WINDOW });
    return false;
  }
  record.count++;
  return record.count > RATE_LIMIT_MAX_REQUESTS;
}

function getClientIP(request: NextRequest): string {
  const forwarded = request.headers.get('x-forwarded-for');
  if (forwarded) return forwarded.split(',')[0].trim();
  const realIP = request.headers.get('x-real-ip');
  if (realIP) return realIP;
  return 'unknown';
}

function ensureDirectoryExists(dirPath: string): void {
  if (!fs.existsSync(dirPath)) {
    fs.mkdirSync(dirPath, { recursive: true });
  }
}

function saveBase64Image(base64Data: string, filename: string): string {
  const base64Content = base64Data.includes(',') ? base64Data.split(',')[1] : base64Data;
  const publicDir = path.join(process.cwd(), 'public', 'generated-images');
  ensureDirectoryExists(publicDir);
  const filePath = path.join(publicDir, filename);
  const imageBuffer = Buffer.from(base64Content, 'base64');
  fs.writeFileSync(filePath, imageBuffer);
  return `/generated-images/${filename}`;
}

export async function POST(request: NextRequest) {
  const startTime = Date.now();

  try {
    const clientIP = getClientIP(request);

    if (isRateLimited(clientIP)) {
      return NextResponse.json(
        { success: false, error: 'RATE_LIMITED', message: 'Too many requests. Please wait a minute.' },
        { status: 429, headers: { 'Retry-After': '60' } }
      );
    }

    const apiKey = process.env.OPENROUTER_API_KEY;
    if (!apiKey) {
      return NextResponse.json(
        { success: false, error: 'SERVICE_UNAVAILABLE', message: 'Image generation service is not configured.' },
        { status: 503 }
      );
    }

    let body: OccasionFlatLayRequest;
    try {
      body = await request.json();
    } catch {
      return NextResponse.json(
        { success: false, error: 'INVALID_REQUEST', message: 'Invalid request format' },
        { status: 400 }
      );
    }

    // Validate occasion preset
    if (!body.occasion || !VALID_PRESETS.includes(body.occasion)) {
      return NextResponse.json(
        { success: false, error: 'INVALID_OCCASION', message: `Invalid occasion. Must be one of: ${VALID_PRESETS.join(', ')}` },
        { status: 400 }
      );
    }

