   741→   *
   742→   * @private
   743→   */
   744→  private parseImageResponse(data: any): { base64?: string; url?: string } {
   745→    // OpenRouter returns images as base64 data URLs in the 'images' array
   746→    // Format: { choices: [{ message: { content: "...", images: ["data:image/png;base64,..."] } }] }
   747→
   748→    try {
