      const mixedCase = `CURATED_ITEMS:
1. Leather Bag | Bag | Brown | A leather crossbody bag
2. Canvas Tote | bag | Beige | A large canvas tote
3. Sneakers | Shoes | White | Minimalist sneakers

IMAGE_PROMPT:
A flat lay image.`;

