    it('scales count references correctly for 5 items', () => {
      const items = [
        { name: 'Top', category: 'Top', color: 'White', visualDescription: 'A top' },
        { name: 'Bottom', category: 'Bottom', color: 'Blue', visualDescription: 'A bottom' },
